const input = $input.first().json;
const credentialsAvailable = Boolean(input.youtube_api_key || input.search_api_key || input.http_source_token);
const sourceCards = [
  {
    source_id: 'src_public_panel_metadata',
    source_type: 'public_video_metadata',
    title: 'Public AI governance panel excerpt candidate',
    locator: 'https://example.invalid/public-ai-governance-panel',
    retrieval_mode: credentialsAvailable ? 'live_metadata_adapter' : 'controlled_fallback_metadata',
    downloaded_media: false,
    transcript_available: false,
    rights_status: 'unknown_requires_review',
    limitation: 'Fallback payload used because HTTP/YouTube credentials were absent; no media was downloaded.'
  },
  {
    source_id: 'src_founder_notes',
    source_type: 'operator_note',
    title: 'Founder notes on reviewable AI workflows',
    locator: 'local_fixture_metadata_only',
    retrieval_mode: 'controlled_fallback_metadata',
    downloaded_media: false,
    transcript_available: false,
    rights_status: 'owned_or_internal_context_requires_editorial_review',
    limitation: 'Local fallback note used to demonstrate source-card capture without external credentials.'
  }
];
return [{ json: { ...input, credentials_available: credentialsAvailable, source_cards: sourceCards, limitations: [
  'Controlled fallback payload used when HTTP/YouTube credentials are absent.',
  'No third-party media was downloaded by this workflow.',
  'Source metadata is not a factual, rights, or publication clearance certification.'
] } }];

const input = $input.first().json;
const quoteCandidates = input.source_cards.map((source, index) => ({
  quote_id: `quote_candidate_${index + 1}`,
  source_id: source.source_id,
  candidate_text_summary: index === 0
    ? 'Candidate quote about review, accountability, and evidence boundaries in AI-assisted work.'
    : 'Candidate framing note about turning AI workflow outputs into reviewer-readable receipts.',
  storage_mode: 'metadata_only',
  audio_visual_downloaded: false,
  review_status: index === 0 ? 'rights_review_required' : 'hold_for_permission_or_replacement'
}));
const claims = [
  {
    claim_id: 'claim_review_boundary_needed',
    claim_text: 'AI-assisted narrative work needs explicit review boundaries before publication decisions.',
    evidence_refs: ['src_public_panel_metadata', 'src_founder_notes'],
    support_level: 'directional_internal_demo_only'
  },
  {
    claim_id: 'claim_receipt_packet_generated',
    claim_text: 'A receipt packet can preserve source cards, quote candidates, claim maps, rights review, ambiguity, and human review state.',
    evidence_refs: ['profusion_cli_receipt_packet'],
    support_level: 'supported_after_local_cli_generation'
  }
];
return [{ json: { ...input, quote_candidates: quoteCandidates, claim_map: claims } }];

const input = $input.first().json;
const rightsReview = input.quote_candidates.map((candidate) => ({
  quote_id: candidate.quote_id,
  rights_classification: candidate.review_status === 'rights_review_required' ? 'review_required_before_use' : 'do_not_use_without_permission_or_replacement',
  publication_state: 'not_publishable_without_human_review',
  no_claims: [
    'does not certify copyright clearance',
    'does not certify fair use',
    'does not prove platform-policy compliance',
    'does not mean the final content is safe to publish'
  ]
}));
const ambiguityRegister = [
  {
    ambiguity_id: 'amb_rights_and_context',
    summary: 'Candidate source context and rights posture remain unresolved because fallback metadata was used.',
    current_status: 'review_required',
    next_review: 'Human editor must confirm source context, permission, replacement path, or removal.'
  },
  {
    ambiguity_id: 'amb_claim_strength',
    summary: 'Claims are demo-bounded and do not establish factual truth or journalistic neutrality.',
    current_status: 'unresolved',
    next_review: 'Human editor must inspect source cards and decide which claims survive.'
  }
];
return [{ json: { ...input, rights_review: rightsReview, ambiguity_register: ambiguityRegister } }];

const input = $input.first().json;
const { execSync } = require('child_process');
const command = 'cd /home/kyle/profusion && uv run profusion m8 demo aice-source-to-narrative-receipt --output-dir /tmp/profusion-aice-p0-1';
let stdout = '';
let stderr = '';
try {
  stdout = execSync(command, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
} catch (error) {
  stdout = error.stdout ? String(error.stdout) : '';
  stderr = error.stderr ? String(error.stderr) : String(error.message || error);
  throw new Error(`Profusion receipt command failed: ${stderr}`);
}
const receiptMatch = String(stdout).match(/Receipt:\s*(.+workflow_receipt\.html)/);
return [{ json: {
  ...input,
  profusion_command: command,
  command_stdout: stdout,
  command_stderr: stderr,
  output_dir: '/tmp/profusion-aice-p0-1',
  receipt_html: receiptMatch ? receiptMatch[1].trim() : null
} }];

const commandResult = $input.first().json;
const stdout = commandResult.command_stdout || commandResult.stdout || commandResult.data || '';
const stderr = commandResult.command_stderr || commandResult.stderr || '';
const receiptMatch = String(stdout).match(/Receipt:\s*(.+workflow_receipt\.html)/);
return [{ json: {
  workflow_slug: 'aice-source-to-narrative-receipt',
  workflow_name: 'AICE Source-to-Narrative Workflow Receipt',
  node_count: 7,
  execution_mode: 'live_n8n_or_controlled_live_fallback',
  profusion_command: commandResult.profusion_command,
  output_dir: '/tmp/profusion-aice-p0-1',
  receipt_html: commandResult.receipt_html || (receiptMatch ? receiptMatch[1].trim() : null),
  command_stdout: stdout,
  command_stderr: stderr,
  limitations: [
    'Controlled fallback payload is used when HTTP/YouTube credentials are absent.',
    'No media is downloaded by this n8n workflow.',
    'The generated receipt does not certify factual truth, copyright clearance, fair use, platform compliance, journalistic neutrality, or publication safety.'
  ]
} }];
